-- Migration 001: schema persona-dialogue (Postgres). SQLite: xem migrations/sqlite/001_init.sql
-- Idempotent: CREATE TABLE IF NOT EXISTS. Xem app/models.py là nguồn sự thật cho cột.
-- (Bản Postgres đầy đủ được sinh từ models; file này giữ các bảng chính để DBA review.)
CREATE TABLE IF NOT EXISTS personas (id VARCHAR(64) PRIMARY KEY, display_name VARCHAR(128) NOT NULL, age INTEGER, region VARCHAR(128) DEFAULT '', stance VARCHAR(32) DEFAULT 'peer_user', style TEXT DEFAULT '', identity_note TEXT DEFAULT '', is_fictional BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS persona_facts (id VARCHAR(32) PRIMARY KEY, persona_id VARCHAR(64) REFERENCES personas(id), fact_key VARCHAR(128) NOT NULL, value TEXT NOT NULL, source VARCHAR(32) DEFAULT 'seed', status VARCHAR(32) DEFAULT 'active', valid_from VARCHAR(32), valid_to VARCHAR(32), version INTEGER DEFAULT 1, provenance TEXT DEFAULT '', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS persona_stories (event_id VARCHAR(64) PRIMARY KEY, persona_id VARCHAR(64) REFERENCES personas(id), title VARCHAR(256) DEFAULT '', summary TEXT NOT NULL, body TEXT NOT NULL, entities JSONB DEFAULT '{}', event_type VARCHAR(64) DEFAULT 'experience', event_date VARCHAR(32), event_date_precision VARCHAR(16) DEFAULT 'unknown', fictional_generated BOOLEAN DEFAULT TRUE, status VARCHAR(32) DEFAULT 'active', version INTEGER DEFAULT 1, told_in_message_id VARCHAR(64), provenance TEXT DEFAULT '', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS story_revisions (id VARCHAR(32) PRIMARY KEY, event_id VARCHAR(64) REFERENCES persona_stories(event_id), persona_id VARCHAR(64) NOT NULL, kind VARCHAR(32) NOT NULL, content TEXT NOT NULL, entities JSONB DEFAULT '{}', version INTEGER DEFAULT 1, status VARCHAR(32) DEFAULT 'active', reason TEXT DEFAULT '', provenance TEXT DEFAULT '', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS product_facts (id VARCHAR(32) PRIMARY KEY, model VARCHAR(128) NOT NULL, trim VARCHAR(128), fact_type VARCHAR(64) NOT NULL, value_text TEXT NOT NULL, value_number DOUBLE PRECISION, unit VARCHAR(64), location VARCHAR(128), source VARCHAR(128) DEFAULT 'sample', verified_at VARCHAR(32), valid_from VARCHAR(32), valid_to VARCHAR(32), status VARCHAR(32) DEFAULT 'active', is_sample BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS actors (id VARCHAR(64) PRIMARY KEY, display_name VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS threads (id VARCHAR(32) PRIMARY KEY, persona_id VARCHAR(64) REFERENCES personas(id), post_id VARCHAR(128) DEFAULT 'post-1', post_text TEXT DEFAULT '', post_vehicle_models JSONB DEFAULT '[]', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id VARCHAR(32) PRIMARY KEY, thread_id VARCHAR(32) REFERENCES threads(id), actor_id VARCHAR(64), role VARCHAR(32) NOT NULL, text TEXT NOT NULL, status VARCHAR(32) DEFAULT 'draft', idempotency_key VARCHAR(128) UNIQUE, trace JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_facts (id VARCHAR(32) PRIMARY KEY, thread_id VARCHAR(32) NOT NULL, actor_id VARCHAR(64) NOT NULL, subject VARCHAR(64) NOT NULL, relation VARCHAR(64), predicate VARCHAR(128) NOT NULL, value_raw TEXT NOT NULL, value_normalized TEXT, evidence TEXT NOT NULL, message_id VARCHAR(64), source VARCHAR(32) NOT NULL, confidence DOUBLE PRECISION DEFAULT 0.8, status VARCHAR(32) DEFAULT 'current', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS question_states (id VARCHAR(32) PRIMARY KEY, thread_id VARCHAR(32) NOT NULL, actor_id VARCHAR(64) NOT NULL, question_key VARCHAR(128) NOT NULL, question_text TEXT NOT NULL, asked_message_id VARCHAR(64), status VARCHAR(32) DEFAULT 'pending', answered_by_message_id VARCHAR(64), answer_field VARCHAR(128), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS deliveries (id VARCHAR(32) PRIMARY KEY, message_id VARCHAR(32) REFERENCES messages(id) UNIQUE, sender VARCHAR(32) DEFAULT 'fake', status VARCHAR(32) NOT NULL, error TEXT, attempted_at TIMESTAMPTZ DEFAULT now());
